/* correct: always close after read() returns 0 */
char buf[4096];
ssize_t n;
while ((n = read(fd, buf, sizeof buf)) > 0)
    handle(buf, n);
if (n < 0) perror("read");
close(fd);                      /* sends our FIN; CLOSE-WAIT -> LAST-ACK */

send(fd, req, reqlen, 0);
shutdown(fd, SHUT_WR);          /* FIN: no more request bytes */
while ((n = recv(fd, buf, sizeof buf, 0)) > 0)
    fwrite(buf, 1, n, stdout);  /* keep reading the reply */
close(fd);

struct linger lg = {.l_onoff = 1, .l_linger = 0};
setsockopt(fd, SOL_SOCKET, SO_LINGER, &lg, sizeof lg);
close(fd);                      /* RST, no FIN, no TIME-WAIT */
